-- Restore the complete Isle of Thunder scenario map (map 1126).
-- Spawn, path, template-state, SmartAI, dialogue, and script data were ported read-only
-- from Legends of Azeroth Pandaria 5.4.8 (build 18414).
-- Legion build 26972 DB2 confirms scenarios 204-209, 211-212 and LFG entries 602-608, 615, 617-618, 621.
START TRANSACTION;

-- Replace any partial map population with one coherent source population.
DELETE ca FROM creature_addon ca INNER JOIN creature c ON c.guid=ca.guid WHERE c.map=1126;
DELETE wp FROM waypoint_data wp INNER JOIN creature c ON c.guid=wp.id WHERE c.map=1126;
DELETE cf FROM creature_formations cf INNER JOIN creature c ON c.guid=cf.memberGUID WHERE c.map=1126;
DELETE cf FROM creature_formations cf INNER JOIN creature c ON c.guid=cf.leaderGUID WHERE c.map=1126;
DELETE gec FROM game_event_creature gec INNER JOIN creature c ON c.guid=gec.guid WHERE c.map=1126;
DELETE pc FROM pool_creature pc INNER JOIN creature c ON c.guid=pc.guid WHERE c.map=1126;
DELETE geg FROM game_event_gameobject geg INNER JOIN gameobject go ON go.guid=geg.guid WHERE go.map=1126;
DELETE pg FROM pool_gameobject pg INNER JOIN gameobject go ON go.guid=pg.guid WHERE go.map=1126;
DELETE FROM `creature` WHERE `map`=1126;
DELETE FROM `gameobject` WHERE `map`=1126;





